begin;

create table public.catalog_sources (
  name text primary key,
  catalog_url text not null check (catalog_url ~ '^https://'),
  pass_date date not null default current_date,
  exhausted boolean not null default false,
  resume_at text not null default '',
  notes text not null default '',
  updated_at timestamptz not null default now()
);
create table public.catalog_reviews (
  id uuid primary key default gen_random_uuid(),
  source text not null references public.catalog_sources(name),
  source_url text not null check (source_url ~ '^https://'),
  company text not null check (length(trim(company)) between 1 and 160),
  title text not null check (length(trim(title)) between 1 and 300),
  merchant_url text not null default '' check (merchant_url = '' or merchant_url ~ '^https://'),
  value text not null default '',
  category text not null default 'Tech',
  deal_type text not null default 'Percent off',
  description text not null default '',
  eligibility text not null default '',
  how_to_redeem text not null default '',
  expires_on date,
  checked_on date,
  status text not null default 'needs_review' check (status in ('needs_review','ready','published','already_covered','excluded','expired')),
  notes text not null default '',
  deal_id uuid references public.deals(id) on delete set null,
  distinct_offer boolean not null default false,
  updated_at timestamptz not null default now(),
  reviewed_by uuid references auth.users(id) on delete set null,
  unique (source, source_url, title)
);
create index catalog_reviews_source_status on public.catalog_reviews(source,status);
create index catalog_reviews_deal_id on public.catalog_reviews(deal_id);
alter table public.catalog_sources enable row level security;
alter table public.catalog_reviews enable row level security;
revoke all on public.catalog_sources, public.catalog_reviews from public, anon, authenticated;
grant select,insert,update on public.catalog_sources,public.catalog_reviews to authenticated;
create policy catalog_sources_admin on public.catalog_sources for all to authenticated
  using ((select public.current_user_is_admin())) with check ((select public.current_user_is_admin()));
create policy catalog_reviews_admin on public.catalog_reviews for all to authenticated
  using ((select public.current_user_is_admin())) with check ((select public.current_user_is_admin()));

create function app_admin_private.stamp_catalog_review()
returns trigger language plpgsql set search_path = '' as $$
begin
  new.updated_at := clock_timestamp();
  if tg_table_name = 'catalog_reviews' then
    new.reviewed_by := auth.uid();
    -- Deleting a linked dashboard deal reopens its review instead of blocking deletion.
    if tg_op = 'UPDATE' and old.deal_id is not null and new.deal_id is null
       and new.status in ('published','already_covered') then
      new.status := 'needs_review';
      new.notes := new.notes || E'\nLinked dashboard listing removed. Review again.';
    end if;
    if new.status in ('published','already_covered') and new.deal_id is null then
      raise exception 'Link a dashboard listing before marking this offer covered.' using errcode = '22023';
    end if;
    if new.distinct_offer and length(trim(new.notes))=0 then
      raise exception 'Describe how this offer differs from existing merchant listings.' using errcode='22023';
    end if;
    if new.status in ('excluded','expired') and length(trim(new.notes)) = 0 then
      raise exception 'Record why this offer was excluded or expired.' using errcode = '22023';
    end if;
    if new.status = 'ready' and (
      new.merchant_url = '' or new.value = '' or new.description = '' or new.eligibility = '' or
      new.how_to_redeem = '' or new.checked_on is null or new.checked_on > current_date or
      (new.expires_on is not null and new.expires_on < current_date)
    ) then
      raise exception 'Check the merchant terms, eligibility, and dates before marking ready.' using errcode = '22023';
    end if;
  end if;
  return new;
end $$;
revoke all on function app_admin_private.stamp_catalog_review() from public, anon, authenticated;
create trigger stamp_catalog_source before update on public.catalog_sources
  for each row execute function app_admin_private.stamp_catalog_review();
create trigger stamp_catalog_review before insert or update on public.catalog_reviews
  for each row execute function app_admin_private.stamp_catalog_review();

create function public.publish_catalog_offer(p_id uuid, p_expected_updated_at timestamptz)
returns uuid language plpgsql security definer set search_path = '' as $$
declare
  candidate public.catalog_reviews%rowtype;
  target_id uuid;
  matches integer;
  prepared public.deals%rowtype;
begin
  if auth.uid() is null or not public.current_user_is_admin() then
    raise exception 'Administrator access required' using errcode='42501';
  end if;
  select * into strict candidate from public.catalog_reviews where id=p_id for update;
  if candidate.updated_at is distinct from p_expected_updated_at then
    raise exception 'This review changed. Refresh before publishing.' using errcode='40001';
  end if;
  if candidate.status <> 'ready' then
    raise exception 'Mark the offer ready before publishing.' using errcode='22023';
  end if;
  if candidate.checked_on is null or candidate.checked_on > current_date or
    (candidate.expires_on is not null and candidate.expires_on < current_date) then
    raise exception 'Check the offer dates before publishing.' using errcode='22023';
  end if;
  lock table public.deals in share row exclusive mode;
  if candidate.deal_id is not null then
    select id into strict target_id from public.deals where id=candidate.deal_id;
  else
    select count(*), (array_agg(d.id))[1] into matches, target_id from public.deals d
    where regexp_replace(lower(d.company),'[^a-z0-9]','','g') = regexp_replace(lower(candidate.company),'[^a-z0-9]','','g')
      and regexp_replace(lower(d.title),'[^a-z0-9]','','g') = regexp_replace(lower(candidate.title),'[^a-z0-9]','','g');
    if matches > 1 then raise exception 'Multiple listings match. Choose the existing listing to update.' using errcode='22023'; end if;
    if matches = 0 and not candidate.distinct_offer and exists(select 1 from public.deals d where
      regexp_replace(lower(d.company),'[^a-z0-9]','','g') = regexp_replace(lower(candidate.company),'[^a-z0-9]','','g')) then
      raise exception 'This merchant is already listed. Link its existing offer or review the distinct terms.' using errcode='22023';
    end if;
  end if;
  select * into prepared from jsonb_populate_record(null::public.deals,jsonb_build_object(
    'company',candidate.company,'title',candidate.title,'category',candidate.category,'deal_type',candidate.deal_type,
    'value',candidate.value,'description',candidate.description,
    'how_to_redeem',candidate.how_to_redeem || ' Eligibility: ' || candidate.eligibility,
    'url',candidate.merchant_url,'expires_at',case when candidate.expires_on is null then null
      else (candidate.expires_on+1)::timestamp at time zone 'America/Denver' end));
  if target_id is null then
    insert into public.deals(company,title,category,deal_type,value,description,how_to_redeem,url,expires_at,is_new,verification_status)
    values(prepared.company,prepared.title,prepared.category,prepared.deal_type,prepared.value,prepared.description,
      prepared.how_to_redeem,prepared.url,prepared.expires_at,true,'verified') returning id into target_id;
  else
    update public.deals set company=prepared.company,title=prepared.title,category=prepared.category,
      deal_type=prepared.deal_type,value=prepared.value,description=prepared.description,
      how_to_redeem=prepared.how_to_redeem,url=prepared.url,expires_at=prepared.expires_at,updated_at=now()
    where id=target_id;
  end if;
  update public.catalog_reviews set status='published',deal_id=target_id where id=p_id;
  return target_id;
end $$;
revoke all on function public.publish_catalog_offer(uuid,timestamptz) from public,anon,authenticated;
grant execute on function public.publish_catalog_offer(uuid,timestamptz) to authenticated;

